import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { bulkArchiveIssuesSchema } from "@/schemas/issue";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as issueService from "@/server/services/issue-service";
import { TenantScopeError } from "@/lib/tenant";
import type { IssueId } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

const ISSUE = "01HZZZSSSSSSSSSSSSSSSSSSSS";

let cleanup: () => void;
let north: Tenant;
let acme: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  north = await createTenant("bulk-north");
  acme = await createTenant("bulk-acme");
});

afterAll(() => {
  cleanup();
});

async function insert(
  tenant: Tenant,
  title: string,
  authorRole: "owner" | "admin" | "member" | "viewer" = "member",
  assigneeRole?: "owner" | "admin" | "member" | "viewer",
) {
  const number = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
  return issueRepo.insertIssue(
    issueInput(tenant.org.id, tenant.project.id, {
      title,
      assigneeId: assigneeRole ? tenant.userIds[assigneeRole] : null,
    }),
    tenant.userIds[authorRole],
    number,
  );
}

describe("bulk archive", () => {
  it("validates the schema bounds", () => {
    const ids = Array.from({ length: 50 }, () => ISSUE);
    expect(bulkArchiveIssuesSchema.parse({ orgId: north.org.id, issueIds: ids }).issueIds).toHaveLength(50);
    expect(bulkArchiveIssuesSchema.safeParse({ orgId: north.org.id, issueIds: [] }).success).toBe(false);
    expect(
      bulkArchiveIssuesSchema.safeParse({
        orgId: north.org.id,
        issueIds: Array.from({ length: 51 }, () => ISSUE),
      }).success,
    ).toBe(false);
    expect(
      bulkArchiveIssuesSchema.safeParse({ orgId: north.org.id, issueIds: ["nope"] }).success,
    ).toBe(false);
  });

  it("findIssuesByIds includes archived, excludes other orgs, and empty is empty", async () => {
    const live = await insert(north, "find live");
    const archived = await insert(north, "find archived");
    await issueRepo.archiveIssue(north.org.id, archived.id);
    const other = await insert(acme, "find other");

    expect(await issueRepo.findIssuesByIds(north.org.id, [])).toEqual([]);

    const found = await issueRepo.findIssuesByIds(north.org.id, [
      live.id,
      archived.id,
      other.id,
      "01HZZZXXXXXXXXXXXXXXXXXXXX" as IssueId,
    ]);
    const ids = found.map((issue) => issue.id).sort();
    expect(ids).toEqual([live.id, archived.id].sort());
    expect(found.find((issue) => issue.id === archived.id)?.archivedAt).not.toBeNull();
  });

  it("archives, skips, dedupes, preserves order, and emits once per archive", async () => {
    const a = await insert(north, "bulk a");
    const b = await insert(north, "bulk b");
    const already = await insert(north, "bulk already");
    const stamped = await issueRepo.archiveIssue(north.org.id, already.id);
    const other = await insert(acme, "bulk other");
    const unknown = "01HZZZYYYYYYYYYYYYYYYYYYYY" as IssueId;

    const received: unknown[] = [];
    const off = subscribe("issue.archived", (payload) => {
      received.push(payload);
    });

    try {
      const result = await issueService.bulkArchiveIssues(north.actors.member, {
        orgId: north.org.id,
        issueIds: [unknown, a.id, already.id, b.id, a.id, other.id, b.id],
      });

      expect(result.archived).toEqual([a.id, b.id]);
      expect(result.skipped).toEqual([unknown, already.id, other.id]);
      expect(received).toHaveLength(2);
      expect(received[0]).toMatchObject({ issueId: a.id, projectId: a.projectId });
      expect(received[1]).toMatchObject({ issueId: b.id, projectId: b.projectId });

      const still = await issueRepo.findIssueById(north.org.id, already.id);
      expect(still?.archivedAt).toBe(stamped.archivedAt);
      expect(still?.updatedAt).toBe(stamped.updatedAt);

      const otherRow = await issueRepo.findIssueById(acme.org.id, other.id);
      expect(otherRow?.archivedAt).toBeNull();
    } finally {
      off();
    }
  });

  it("lets a viewer archive issues they authored or are assigned to", async () => {
    const authored = await insert(north, "viewer authored", "viewer");
    const assigned = await insert(north, "viewer assigned", "member", "viewer");

    const result = await issueService.bulkArchiveIssues(north.actors.viewer, {
      orgId: north.org.id,
      issueIds: [assigned.id, authored.id],
    });

    expect(result.archived).toEqual([assigned.id, authored.id]);
    expect(result.skipped).toEqual([]);
  });

  it("rejects the whole call when any issue fails the permission check", async () => {
    const owned = await insert(north, "viewer owns this", "viewer");
    const foreign = await insert(north, "viewer does not own", "member");
    const already = await insert(north, "skipped archived", "member");
    await issueRepo.archiveIssue(north.org.id, already.id);

    const received: unknown[] = [];
    const off = subscribe("issue.archived", (payload) => {
      received.push(payload);
    });

    try {
      await expect(
        issueService.bulkArchiveIssues(north.actors.viewer, {
          orgId: north.org.id,
          issueIds: [already.id, owned.id, foreign.id],
        }),
      ).rejects.toBeInstanceOf(PermissionDeniedError);

      expect(received).toEqual([]);
      expect((await issueRepo.findIssueById(north.org.id, owned.id))?.archivedAt).toBeNull();
      expect((await issueRepo.findIssueById(north.org.id, foreign.id))?.archivedAt).toBeNull();
    } finally {
      off();
    }
  });

  it("rejects a cross-tenant org id", async () => {
    const issue = await insert(north, "scope target");
    await expect(
      issueService.bulkArchiveIssues(acme.actors.owner, {
        orgId: north.org.id,
        issueIds: [issue.id],
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);
    expect((await issueRepo.findIssueById(north.org.id, issue.id))?.archivedAt).toBeNull();
  });

  it("skips only, with no permission check, when nothing is archivable", async () => {
    const already = await insert(north, "only archived");
    await issueRepo.archiveIssue(north.org.id, already.id);
    const unknown = "01HZZZZZZZZZZZZZZZZZZZZZZZ" as IssueId;

    const result = await issueService.bulkArchiveIssues(north.actors.viewer, {
      orgId: north.org.id,
